def q(n, t, stem, opts, key, skill, level, ev, expl, kw_ok, notes, fixed=False, negative=False, changes=""):
    """notes: {letter: (kk, [evidence], [kw kk])}"""
    Q.append({"id": f"l1v3-q{n}", "number": n, "text_id": f"l1v3-t{t}", "stem": stem,
              "options": dict(zip("ABCD", opts)), "key": key, "skill": skill, "skill_name": SKILLS[skill],
              "level": level, "negative": negative, "fixed_order": fixed,
              "evidence": ev, "explanation": expl,
              "distractor_notes": {k: v[0] for k, v in notes.items()},
              "distractor_evidence": {k: [re.sub(r"\s*\([^)]*(азатжол|бөлім)[^)]*\)$", "", e) for e in v[1]] for k, v in notes.items()},
              "keywords": dict({"ok": {"kk": kw_ok, "ru": []}},
                               **{k: {"kk": v[2], "ru": []} for k, v in notes.items() if v[1]}),
              "editor_changes": changes})

