# ---------- Тексерістер ----------
strip = lambda e: re.sub(r"\s*\([^)]*(азатжол|бөлім)[^)]*\)$", "", e)
errs = 0
for x in Q:
    assert x["key"] in "ABCD" and len(x["options"]) == 4
    assert set(x["distractor_notes"]) == set("ABCD") - {x["key"]}, x["id"]
    body = " ".join(next(t for t in texts if t["id"] == x["text_id"])["paragraphs"]).replace("**", "")
    groups = [("ok", x["evidence"])] + [(k, v) for k, v in x["distractor_evidence"].items() if v]
    for k, evs in groups:
        for e in evs:
            for frag in [f.strip(" .") for f in strip(e).split("...")]:
                if frag and frag not in body: print("ДӘЛЕЛ ТАБЫЛМАДЫ:", x["id"], k, "|", frag); errs += 1
        kk_all = " ".join(strip(e) for e in evs)
        for w in x["keywords"].get(k, {"kk": []})["kk"]:
            if w.lower() not in kk_all.lower(): print("КІЛТ СӨЗ ЖОҚ:", x["id"], k, "|", w); errs += 1
    # Қате нұсқалар дұрыс жауаптан қысқа болмасын (біреуі ғана сәл қысқа болуы мүмкін)
    if not x["fixed_order"]:
        kl = len(x["options"][x["key"]]); short = [l for l, o in x["options"].items() if l != x["key"] and len(o) < kl]
        if len(short) > 1: print("НҰСҚАЛАР ҚЫСҚА:", x["id"], {l: len(o) for l, o in x["options"].items()}, "кілт", kl)
for t in texts: assert t["source_note"], t["id"]
assert [x["number"] for x in Q] == list(range(1, 21))
assert not errs, errs

bank = {"bank_id": "kaz-L1-v3", "track": "first_language",
        "source": "Автордың құрастырған нұсқасы: НЗМ үлгісінің деңгейінде, мәтіндер қазақстандық сайттардан алынған (әр мәтіннің source_note өрісін қараңыз)",
        "skills": SKILLS, "evidence_ru": {}, "style_notes": [], "texts": texts, "items": Q}
(OUT / "bank_l1_v3.json").write_text(json.dumps(bank, ensure_ascii=False, indent=2), encoding="utf-8")
from collections import Counter
print("items", len(Q), "keys", Counter(x["key"] for x in Q), "skills", Counter(x["skill"][0] for x in Q), "levels", Counter(x["level"] for x in Q))
for t in texts: print(t["id"], len(" ".join(t["paragraphs"]).split()), "сөз")

# ---------- Мұғалімге арналған тексеру құжаты ----------
md = ["# Қазақ тілі (бірінші тіл) – 3-нұсқа: тапсырмалар банкі", "",
      "Бағыт: **бірінші тіл** (қазақ сыныптары). Құрылымы мен деңгейі НЗМ үлгісіне (2-нұсқа) сай.",
      "Мәтіндер қазақстандық сайттардан алынды: тек қысқартылды, емле мен тыныс белгі түзетулері әр мәтіннің астында көрсетілген.", ""]
for t in texts:
    md += [f"## {t['id'].split('-t')[1]}-мәтін" + (f": {t['title']}" if t["title"] else ""), "", f"*Дереккөз:* {t['source_note']}", ""]
    if t["id"] in TEXT_CHANGES: md += [f"*Редакциялық түзету:* {TEXT_CHANGES[t['id']]}", ""]
    for i, p in enumerate(t["paragraphs"], 1):
        md += [(f"{i}. " if t["numbered_paragraphs"] else "") + p, ""]
    for x in [x for x in Q if x["text_id"] == t["id"]]:
        md += [f"### {x['number']}. " + x["stem"].replace("\n", "  \n"), ""]
        md += [f"- **{k})** {v}" + ("  ✅" if k == x["key"] else "") for k, v in x["options"].items()]
        md += ["", f"*Дағды:* {x['skill']} – {x['skill_name']} · *Деңгей:* {x['level']}", "", "**Мәтіндегі дәлел:**"]
        md += [f"> {e}" for e in x["evidence"]]
        md += ["", f"**Түсініктеме:** {x['explanation']}", "", "**Қалған нұсқалар неге қате:**"]
        for k in sorted(x["distractor_notes"]):
            v = x["distractor_notes"][k]; ev = x["distractor_evidence"][k]
            md.append(f"- {k}) {v[:1].upper()+v[1:]}" + (" Дәлел: «" + "», «".join(ev) + "»" if ev else ""))
        md += ["", "---", ""]
(OUT.parent / "docs" / "1-3-nusqa-tekseru.md").write_text("\n".join(md), encoding="utf-8")
